import unittest


class AgentTest_get_all_major(unittest.TestCase):

    def setUp(self):
        self.registration_system = ClassRegistrationSystem()

    def test_get_all_major_1(self):
        # An empty system has no majors.
        result = self.registration_system.get_all_major()
        self.assertEqual(result, [])

    def test_get_all_major_2(self):
        # A single student with one major returns a list containing that major.
        self.registration_system.students = [
            {"name": "John", "major": "Computer Science"}
        ]
        result = self.registration_system.get_all_major()
        self.assertEqual(result, ["Computer Science"])

    def test_get_all_major_3(self):
        # Majors from all students in the system are returned.
        self.registration_system.students = [
            {"name": "John", "major": "Computer Science"},
            {"name": "Alice", "major": "Mathematics"},
            {"name": "Bob", "major": "Physics"},
        ]
        result = self.registration_system.get_all_major()
        self.assertIsInstance(result, list)
        self.assertCountEqual(result, ["Computer Science", "Mathematics", "Physics"])

    def test_get_all_major_4(self):
        # Several students sharing a major: the major is listed only once.
        self.registration_system.students = [
            {"name": "John", "major": "Computer Science"},
            {"name": "Bob", "major": "Computer Science"},
            {"name": "Alice", "major": "Mathematics"},
        ]
        result = self.registration_system.get_all_major()
        self.assertEqual(len(result), 2)
        self.assertCountEqual(result, ["Computer Science", "Mathematics"])

    def test_get_all_major_5(self):
        # Majors of students added through register_student are returned.
        self.registration_system.register_student(
            {"name": "John", "major": "Computer Science"}
        )
        self.registration_system.register_student(
            {"name": "Alice", "major": "Mathematics"}
        )
        result = self.registration_system.get_all_major()
        self.assertCountEqual(result, ["Computer Science", "Mathematics"])


if __name__ == "__main__":
    unittest.main()
